namespace TriReviewBridge {
 public partial class WorkbenchApp {
  bool HybridMode;string HybridSelfTest;
  bool NativeMode {get{return RelayMode||HybridMode;}}
  const string HybridApprovalNotice="HYBRID_NATIVE 当前仅支持普通文字对话与纯文字任务；正式审批、附件及自主协作链尚未接入。回复不代表实施授权。";
  string NativeApprovalNotice {get{return HybridMode?HybridApprovalNotice:RelayApprovalNotice;}}
  void ReadHybridMode(){var cfg=Json.Codec.DeserializeObject(File.ReadAllText(Config));HybridMode=Json.Str(cfg,"mode")=="HYBRID_NATIVE";if(HybridMode&&Json.Str(cfg,"profileId")!="hybrid-native-001")throw new InvalidOperationException("三方候选 profileId 不匹配。");}
  void ValidateHybridHealth(object health){if(HybridMode){if(Json.Str(health,"mode")!="HYBRID_NATIVE"||Json.Str(health,"profileId")!="hybrid-native-001"||Json.Bool(health,"formalReviewAvailable")||Json.Bool(health,"independentRuntime"))throw new InvalidOperationException("三方候选 Host 身份或能力声明不匹配。");if(!String.IsNullOrEmpty(SelfTest)||!String.IsNullOrEmpty(RelaySelfTest))throw new InvalidOperationException("旧自测入口不能用于三方原生候选。");}if(!String.IsNullOrEmpty(HybridSelfTest)){string tests=Path.GetFullPath(Path.Combine(Root,"test-output"))+Path.DirectorySeparatorChar;if(!HybridMode||!Path.GetFullPath(Config).StartsWith(tests,StringComparison.OrdinalIgnoreCase)||!String.Equals(Path.GetDirectoryName(Path.GetFullPath(HybridSelfTest)),Path.GetDirectoryName(Path.GetFullPath(Config)),StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("三方原生自测只允许 test-output 内虚构 Host 与同目录证据。");}}
  string HybridRoleName(string role){if(role=="deepseek"&&HasDesktopRelay())return "DSH · Codex电脑接力";return role=="hermes"?"Hermes原会话":role=="deepseek"?"DSH原会话":role=="chatgpt"?"ChatGPT原会话":role;}
  string HybridStateName(string state){switch((state??"").ToLowerInvariant()){case "queued":return "已排队 · 等待接入可发送";case "leased":case "sending":return "正在投递 · 原会话收件待确认";case "submitted":return "已提交 · 原会话收件尚未确认";case "received":return "已收到原会话回复";case "unknown":return "UNKNOWN · 结果未知，不自动重发";case "expired":return "已过期 · 未完成";case "text_task_accepted":return "用户已接受文字结果 · 非实施授权";default:return StateName(state);}}
  string HybridParticipantLabel(object participant){if(IsDesktopRelay(participant))return DesktopRelayParticipantLabel(participant);if(Json.Str(participant,"status")=="inactive")return "未参与";if(Json.Str(participant,"kind")!="hybrid_native")return "未绑定原会话引用";bool verified=Json.Str(participant,"verificationLevel")=="WORKER_REPORTED_IDENTITY_MATCH";bool paused=Json.Bool(participant,"paused")||Json.Str(participant,"status")=="paused";return (paused?"已暂停投递":verified?"身份由执行者回报匹配":"原会话身份未验证")+" · "+(Json.Bool(participant,"queueAvailable")?"可排队":"不可排队")+(paused&&!verified?" · 身份未验证":"")+(Json.Bool(participant,"dispatchAvailable")?" · 后端允许发送":" · 当前不可发送");}
  string HybridRecipientHint(){return "接收对象："+(Chosen().Length==0?"未选":String.Join("、",Chosen().Select(Name)))+"。暂停或未验证仍可排队；排队不代表已发出。";}
  object HybridSelectedParticipant(){var selected=C<ListBox>("HybridRoleSelect").SelectedItem as ListBoxItem;return selected==null?null:Json.Arr(Json.Get(State,"participants")).FirstOrDefault(p=>Json.Str(p,"id")==Convert.ToString(selected.Tag));}
  void RefreshHybridRoleControl(){if(!HybridMode)return;var p=HybridSelectedParticipant();bool bound=p!=null&&Json.Str(p,"kind")=="hybrid_native";bool verified=bound&&HybridIdentityReported(p);bool enableAvailable=bound&&Json.Bool(Json.Get(p,"roleControl"),"enableAvailable");C<Button>("HybridPrepareButton").IsEnabled=bound;C<Button>("HybridPauseButton").IsEnabled=bound;C<Button>("HybridEnableButton").IsEnabled=bound&&enableAvailable&&Json.Bool(p,"paused");C<Button>("HybridEnableButton").ToolTip=enableAvailable?"仅启用所选角色；保留其他角色暂停。":(String.IsNullOrEmpty(Json.Str(Json.Get(p,"roleControl"),"enableBlockReason"))?"待原生执行者核对指定原会话身份后才可启用。":Json.Str(Json.Get(p,"roleControl"),"enableBlockReason"));C<TextBlock>("HybridRoleStatusText").Text=p==null?"选择角色后查看后端状态。":HybridParticipantLabel(p)+"\n"+(IsDesktopRelay(p)?DesktopRelayPreparationText(p):Json.Bool(p,"preparationRequested")?"已登记准备请求；准备不等于身份验证。":"尚无准备请求。")+"\n"+(IsDesktopRelay(p)?DesktopRelayDetails(p):verified?"身份匹配来自执行者回报，非平台独立认证。":"待原生身份核对；界面不能代填身份回执。")+"\n"+(enableAvailable?"后端允许明确启用该角色。":Json.Str(Json.Get(p,"roleControl"),"enableBlockReason"));}
  async Task HybridRoleAction(string action){if(!HybridMode)throw new InvalidOperationException("当前不是三方候选模式。");var p=HybridSelectedParticipant();if(p==null||Json.Str(p,"kind")!="hybrid_native")throw new InvalidOperationException("请选择已绑定引用的角色。");if(action=="enable"&&!Json.Bool(Json.Get(p,"roleControl"),"enableAvailable"))throw new InvalidOperationException(String.IsNullOrEmpty(Json.Str(Json.Get(p,"roleControl"),"enableBlockReason"))?"待原生身份核对；准备请求不能替代验证。":Json.Str(Json.Get(p,"roleControl"),"enableBlockReason"));string role=Json.Str(p,"id");if(action=="prepare"&&role=="hermes"&&String.IsNullOrEmpty(HybridSelfTest)){await ConfirmAndStartHermesWatch();return;}await Client.Call("/api/hybrid/role-control",Json.D("role",role,"action",action,"note","用户在三方候选中明确选择 "+role+" / "+action));await RefreshWorkspace();Note(HybridRoleName(role)+"：已向后端提交"+(action=="prepare"?"准备请求（身份仍待核对）":action=="pause"?"单角色暂停":"单角色启用")+"；其他角色状态不变。");}
  void RefreshHybridTaskAcceptControl(){if(!HybridMode)return;var row=Items.SelectedItem as ItemRow;bool ready=UxScopeMatches()&&UxContextKind=="item"&&row!=null&&Json.Str(row.Raw,"scope")=="text_only_task"&&Json.Str(row.Raw,"state")=="awaiting_user_acceptance";C<Button>("HybridAcceptTaskButton").IsEnabled=ready;C<Button>("HybridAcceptTaskButton").ToolTip=ready?"仅接受所选纯文字任务的当前结果，不授予工程实施权限。":"请在任务页明确选中已有完整结果、等待用户接受的纯文字任务。";}
  async Task HybridAcceptTask(){RefreshHybridTaskAcceptControl();if(!C<Button>("HybridAcceptTaskButton").IsEnabled)throw new InvalidOperationException("请明确选中已有完整结果的纯文字任务。");var row=(ItemRow)Items.SelectedItem;await Post("task-accept","itemId",row.Id,"expectedRevision",Convert.ToInt32(row.Revision),"artifactHash",Json.Str(row.Raw,"artifactHash"),"note","用户明确接受所选纯文字结果；非工程实施授权");await RefreshWorkspace();Note("已记录纯文字结果接受；工程实施授权仍未授予。");}
  async Task ConfirmAndStartHermesWatch(){const string explanation="仅允许固定Hermes原会话Nagi的本机持续Worker，绑定的原Session保持固定。\n\n现有SDK可能通过policy.refresh，把Hermes现有配置中的推理默认、工具集、MCP、terminal、max_turns等同步或提交到原会话；不主动指定新模型不代表设置完全不变。\n\n读取会话快照及本次完整result时，SDK内存中可能包含历史和工具上下文；虽然Bridge仅导出本次结果，这不代表SDK没有读取上述上下文。\n\n关闭此窗口后Worker可继续运行；暂停停止新投递，仍需回收在途回执。身份核对结果由后台单独回报，启用Hermes仍须另行明确操作。\n\n本次只记录本机确认，不是外部审计。是否允许上述持续原生访问？";bool confirmed=MessageBox.Show(Win,explanation,"Hermes持续本机接入许可",MessageBoxButton.YesNo,MessageBoxImage.Warning,MessageBoxResult.No)==MessageBoxResult.Yes;var result=await HermesWatchConsent.PrepareAndStart(Config,confirmed,async()=>{await Client.Call("/api/hybrid/role-control",Json.D("role","hermes","action","prepare","note","用户本人确认持续本机访问后准备；角色保持暂停"));});if(result.State=="CANCELLED_NO_ACTION"){Note("已取消Hermes本机准备；未启动执行器。");return;}await RefreshWorkspace();Note(result.State=="EXISTING_LOCK_NO_START"?"已有Hermes执行器锁，未重复启动或清锁；身份核对仍等待后台回报。":"已提交Hermes本机启动信号；身份与连接尚未确认，角色保持暂停。");}
  void SetupHybridPresentation(){if(!HybridMode||!UxMode)return;Win.Title="TriReviewBridge · 三方原会话协作候选";C<TextBlock>("ModeBadge").Text="三方原生候选";C<TextBlock>("ModeWindowNote").Text="关闭窗口不会停止队列。三方原会话引用保持固定；启用与暂停逐角色记录。";C<TextBlock>("ModeBoundaryText").Text="三方初始暂停、身份未验证。可先排队；明确启用须有原生身份核对回报。Worker 活动不等于 Agent 在线。UNKNOWN 不自动重发。";Composer.ToolTip="支持指定接收方普通文字对话，及指定一名执行者的纯文字任务；正式审批、附件、自主链尚未接入。";foreach(string id in new[]{"BindButton","PauseBindingButton","ParticipantsButton","NewProjectButton","NewWorkspaceButton","NewReviewButton","MessageReviewButton","ReviseButton","AuthorizeButton","CrossButton","ReviewRecordButton","ForwardButton","AttachKnowledgeButton","KnowledgeButton","ProjectSettingsButton","ObservationButton","StopBackendButton"}){var button=C<Button>(id);if(button!=null){button.IsEnabled=false;button.ToolTip=HybridApprovalNotice;}}C<Button>("HybridEarlierHistoryButton").Visibility=Visibility.Visible;Hook("HybridEarlierHistoryButton",OpenHybridEarlierHistory);C<Button>("HybridAcceptTaskButton").Visibility=Visibility.Visible;Hook("HybridAcceptTaskButton",HybridAcceptTask);Discussion.IsEnabled=false;((TabItem)MainTabs().Items[1]).Header="纯文字任务";((TabItem)MainTabs().Items[2]).Visibility=Visibility.Collapsed;((TabItem)MainTabs().Items[3]).Visibility=Visibility.Collapsed;C<StackPanel>("HybridRoleControls").Visibility=Visibility.Visible;var select=C<ListBox>("HybridRoleSelect");foreach(string role in new[]{"hermes","deepseek","chatgpt"})select.Items.Add(new ListBoxItem(){Content=HybridRoleName(role),Tag=role});select.SelectedIndex=0;select.SelectionChanged+=(s,e)=>RefreshHybridRoleControl();Hook("HybridPrepareButton",()=>HybridRoleAction("prepare"));Hook("HybridEnableButton",()=>HybridRoleAction("enable"));Hook("HybridPauseButton",()=>HybridRoleAction("pause"));RefreshHybridRoleControl();Note("三方原会话候选 · 正在核对独立本机 Host。");}
  void AppendHybridContext(List<string> issues){RefreshDesktopRelayLabels();RefreshHybridHistoryControl();RefreshHybridTaskAcceptControl();var members=Json.Arr(Json.Get(State,"participants")).Where(p=>Json.Str(p,"status")!="inactive").ToArray();var workers=Json.Get(State,"workers");foreach(var p in members){string role=Json.Str(p,"id"),last=Json.Str(Json.Get(workers,role),"lastSeenAt");if(!String.IsNullOrEmpty(last))C<TextBlock>("ContextParticipantsText").Text+="\n"+HybridRoleName(role)+" 执行者最近活动 "+LocalTime(last)+"（不代表 Agent 在线）";if(IsDesktopRelay(p))AppendDesktopRelayContext(issues,p);else if(Json.Str(p,"verificationLevel")!="WORKER_REPORTED_IDENTITY_MATCH")issues.Add(HybridRoleName(role)+"身份待核对");}if(members.Any(p=>Json.Bool(p,"paused")))issues.Add("部分角色暂停投递，消息可保留排队");C<TextBlock>("ContextMaterialText").Text="当前仅文字；附件和原字节交付尚未接入。";C<TextBlock>("ContextReviewText").Text=HybridApprovalNotice;RefreshHybridRoleControl();}
  string CaptureHybridPreview(){Win.UpdateLayout();string path=HybridSelfTest+".png";var bitmap=new RenderTargetBitmap((int)Math.Ceiling(Win.ActualWidth),(int)Math.Ceiling(Win.ActualHeight),96,96,PixelFormats.Pbgra32);bitmap.Render(Win);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var output=File.Create(path))encoder.Save(output);return path;}
  async Task RunHybridSelfTest(){if(!HybridMode||UxThemeName!="dark")throw new Exception("Hybrid mode or default dark theme missing");if(Receivers.Items.Cast<ListBoxItem>().Count(x=>x.IsEnabled)!=3||Chosen().Length!=0)throw new Exception("Paused/unverified bindings cannot queue");if(C<Button>("NewReviewButton").IsEnabled||C<Button>("BindButton").IsEnabled)throw new Exception("Unsupported native operations enabled");if(C<StackPanel>("HybridRoleControls").Visibility!=Visibility.Visible)throw new Exception("Single-role controls missing");Composer.Text="你好";await Send();if(Composer.Text!="你好"||Json.Arr(Json.Get(State,"deliveries")).Length!=0||Json.Arr(Json.Get(State,"messages")).Length!=0)throw new Exception("No-target ordinary chat queued or lost its draft");Composer.Text="@ChatGPT 你好";await Send();await RefreshWorkspace();var direct=Json.Arr(Json.Get(State,"deliveries"));if(direct.Length!=1||Json.Str(direct[0],"role")!="chatgpt")throw new Exception("Explicit ChatGPT address did not target only ChatGPT");Composer.Text="@Hermes @DSH @ChatGPT 虚构三方界面联调：请只回复三种虚构颜色。";await Send();await RefreshWorkspace();var ds=Json.Arr(Json.Get(State,"deliveries"));if(ds.Count(entry=>Json.Str(entry,"state")=="queued")!=4)throw new Exception("Three-recipient chat was not queued");var d=ds[0];var user=Json.Arr(Json.Get(State,"messages")).First(m=>Json.Str(m,"author")=="user"&&Json.Str(m,"case_id")==Json.Str(d,"caseId"));string original=Json.Str(d,"state");try{Json.Obj(d)["state"]="submitted";if(!UxDeliverySummary(user,new[]{d}).Contains("收件尚未确认"))throw new Exception("Submitted displayed as receipt");Json.Obj(d)["state"]="unknown";if(!UxDeliverySummary(user,new[]{d}).Contains("结果未知"))throw new Exception("UNKNOWN displayed as success");RefreshUxContext();if(!C<TextBlock>("AttentionText").Text.Contains("不自动重发"))throw new Exception("UNKNOWN warning hidden");}finally{Json.Obj(d)["state"]=original;}C<ListBox>("HybridRoleSelect").SelectedIndex=0;await HybridRoleAction("prepare");var hermes=Json.Arr(Json.Get(State,"participants")).Single(p=>Json.Str(p,"id")=="hermes");if(!Json.Bool(hermes,"preparationRequested")||!Json.Bool(hermes,"paused")||Json.Str(hermes,"verificationLevel")!="UNVERIFIED"||C<Button>("HybridEnableButton").IsEnabled)throw new Exception("Prepare became identity verification or enable");C<ListBox>("HybridRoleSelect").SelectedIndex=2;await HybridRoleAction("enable");if(Json.Arr(Json.Get(State,"participants")).Any(p=>Json.Str(p,"id")!="chatgpt"&&!Json.Bool(p,"paused")))throw new Exception("Enabling one role enabled others");await HybridRoleAction("pause");if(Json.Arr(Json.Get(State,"participants")).Any(p=>!Json.Bool(p,"paused")))throw new Exception("Single role pause did not persist");await RunDesktopRelaySelfTest();bool locked=false;try{await NewReview("虚构正式审批",null);}catch(InvalidOperationException){locked=true;}if(!locked)throw new Exception("Formal review opened");Composer.Text="@Hermes 整理虚构颜色说明，只输出文字。";await Send();await RefreshWorkspace();if(!Json.Arr(Json.Get(State,"items")).Any(i=>Json.Str(i,"scope")=="text_only_task"))throw new Exception("Main composer text task failed");var taskRow=Items.ItemsSource.Cast<ItemRow>().Last(i=>Json.Str(i.Raw,"scope")=="text_only_task");Items.SelectedItem=taskRow;UxContextKind="item";RefreshUxContext();await HybridAcceptTask();var accepted=Json.Arr(Json.Get(State,"items")).Single(i=>Json.Str(i,"id")==taskRow.Id);if(Json.Str(accepted,"state")!="text_task_accepted"||Json.Bool(accepted,"userAuthorized")||Json.Bool(accepted,"executionAuthorized"))throw new Exception("Text result acceptance became implementation authorization");string draft="虚构历史窗口操作后的未发送草稿";Composer.Text=draft;string[] targets=Chosen();string selected=UxContextKind;int messageCount=Messages.Items.Count;await OpenHybridEarlierHistory();await HybridHistoryLoadMore();if(HybridHistoryCount!=3||Composer.Text!=draft||!Chosen().SequenceEqual(targets)||UxContextKind!=selected||Messages.Items.Count!=messageCount)throw new Exception("Earlier history crossed main input/context/recipient boundary");HybridHistoryWindow.Close();MainTabs().SelectedIndex=1;await Task.Delay(180);Win.UpdateLayout();string image=CaptureHybridPreview();File.WriteAllText(HybridSelfTest,Json.Show(Json.D("passed",true,"mode","HYBRID_NATIVE","theme",UxThemeName,"pausedUnverifiedQueueSelectable",true,"defaultRecipientsEmpty",true,"noTargetOrdinaryChatKeepsDraftWithoutQueue",true,"explicitChatGPTTargetsOnlyC",true,"threeRecipientChatQueued",true,"prepareDoesNotVerify",true,"enableOnlySelectedVerifiedRole",true,"pauseOnlySelectedRole",true,"submittedNotReceipt",true,"unknownNotSuccessOrResent",true,"mainComposerTextTask",true,"explicitTextResultAccepted",true,"executionAuthorized",false,"formalReviewLocked",true,"preview",image,"earlierHistoryPagedReadonly",true,"historyPreservesDraftContextRecipients",true,"renderMethod","WPF RenderTargetBitmap; not desktop screenshot","desktopRelay",DesktopRelayProof,"realSessionOperations",0)),System.Text.Encoding.UTF8);Win.Close();}
 }
